#!/usr/bin/env sh
# fetch 志賀町コミュニティバスしかばす (XX) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://ckan.opendata.pref.ishikawa.lg.jp/dataset/65de3540-4781-4329-bc8f-634870e5a69c/resource/cfb1baaa-4808-408b-ab09-2f3a0a08aacb/download"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
